-- ============================================================
-- Mapa del campus · Bloque 2 (2A y 2B)
-- Generado a partir de BLOQUE_2A_08-02-2019_OK.dwg y BLOQUE_2B_07-02-2019_OK.dwg:
-- imagen de cada planta y polígono de cada espacio (capa AREA/AREAS del plano),
-- en píxeles de la imagen (L.CRS.Simple: x desde la izquierda, y desde abajo).
--
-- Requiere V2__mapa_infraestructura.sql. Se puede ejecutar varias veces:
--   psql -U postgres -d ucc_orientacion -1 -f db/datos_mapa_bloque2.sql
--
-- Si ya existe un espacio con el mismo código, solo se le asigna el plano y el polígono.
-- Los espacios de servicio (aseo, bodegas, cuarto de bombas) quedan inactivos: el
-- administrador puede activarlos desde el panel.
-- ============================================================

SET client_min_messages = warning;

-- Plano Bloque 2A · Piso 1 (2200 x 1060 px)
INSERT INTO plano (id, nombre, edificio, piso, imagen, ancho, alto, activo) VALUES (
